// The page tree is hand-written rather than generated by Folio, so malformed
// references and misleading /Count values reach the public parser unchanged.
func pageTreePDF(nodes ...string) []byte {
	objects := append([]string{"<< /Type /Catalog /Pages 2 0 R >>"}, nodes...)
	var pdf bytes.Buffer
	pdf.WriteString("%PDF-1.7\n")
	offsets := make([]int, len(objects))
	for i, obj := range objects {
		offsets[i] = pdf.Len()
		fmt.Fprintf(&pdf, "%d 0 obj\n%s\nendobj\n", i+1, obj)
	}
	xref := pdf.Len()
	fmt.Fprintf(&pdf, "xref\n0 %d\n0000000000 65535 f \n", len(objects)+1)
	for _, offset := range offsets {
		fmt.Fprintf(&pdf, "%010d 00000 n \n", offset)
	}
	fmt.Fprintf(&pdf, "trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n", len(objects)+1, xref)
	return pdf.Bytes()
}

func TestPageTreeRevisit(t *testing.T) {
	for name, nodes := range map[string][]string{
		"self cycle": {"<< /Type /Pages /Kids [2 0 R] /Count 1 >>"},
		"ancestor cycle": {
			"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
			"<< /Type /Pages /Kids [2 0 R] /Count 1 >>",
		},
		"duplicate leaf": {
			"<< /Type /Pages /Kids [3 0 R 3 0 R] /Count 2 >>",
			"<< /Type /Page >>",
		},
		"shared subtree": {
			"<< /Type /Pages /Kids [3 0 R 4 0 R] /Count 2 >>",
			"<< /Type /Pages /Kids [5 0 R] /Count 1 >>",
			"<< /Type /Pages /Kids [5 0 R] /Count 1 >>",
			"<< /Type /Page >>",
		},
		"indirect Kids": {
			"<< /Type /Pages /Kids 3 0 R /Count 1 >>",
			"[2 0 R]",
		},
	} {
		for _, strictness := range []Strictness{StrictnessStrict, StrictnessTolerant} {
			for _, cache := range []int{0, 1} {
				t.Run(fmt.Sprintf("%s/strictness=%d/cache=%d", name, strictness, cache), func(t *testing.T) {
					_, err := ParseWithOptions(pageTreePDF(nodes...), ReadOptions{
						Strictness: strictness, MaxCache: cache,
						MemoryLimits: MemoryLimits{MaxObjectCount: 100},
					})
					if err == nil || !strings.Contains(err.Error(), "revisits") {
						t.Fatalf("expected revisit error, got %v", err)
					}
				})
			}
		}
	}
}

func deepPageTree(depth int) []byte {
	nodes := make([]string, depth)
	for i := range depth - 1 {
		nodes[i] = fmt.Sprintf("<< /Type /Pages /Kids [%d 0 R] /Count 1 /MediaBox [0 0 200 300] >>", i+3)
	}
	nodes[depth-1] = "<< /Type /Page >>"
	return pageTreePDF(nodes...)
}

func TestPageTreeDepth(t *testing.T) {
	for _, strictness := range []Strictness{StrictnessStrict, StrictnessTolerant} {
		t.Run(fmt.Sprint(strictness), func(t *testing.T) {
			r, err := ParseWithOptions(deepPageTree(100), ReadOptions{Strictness: strictness})
			if err != nil || r.PageCount() != 1 {
				t.Fatalf("depth 100 must succeed: reader=%v, error=%v", r, err)
			}
			page, err := r.Page(0)
			if err != nil || page.Width != 200 || page.Height != 300 {
				t.Fatalf("inherited page size lost: page=%v, error=%v", page, err)
			}
			for _, depth := range []int{101, 1000} {
				if _, err := ParseWithOptions(deepPageTree(depth), ReadOptions{Strictness: strictness}); err == nil || !strings.Contains(err.Error(), "depth exceeds limit 100") {
					t.Fatalf("depth %d: expected depth error, got %v", depth, err)
				}
			}
		})
	}
}

func widePageTree(pages int) []byte {
	var kids strings.Builder
	nodes := make([]string, pages+1)
	for i := range pages {
		fmt.Fprintf(&kids, "%d 0 R ", i+3)
		nodes[i+1] = fmt.Sprintf("<< /Type /Page /MediaBox [0 0 %d 200] >>", i+1)
	}
	// Deliberately underreport Count. Only actual leaf visits enforce the cap.
	nodes[0] = fmt.Sprintf("<< /Type /Pages /Kids [%s] /Count 1 >>", &kids)
	return pageTreePDF(nodes...)
}

func TestPageTreePageLimit(t *testing.T) {
	for _, strictness := range []Strictness{StrictnessStrict, StrictnessTolerant} {
		t.Run(fmt.Sprint(strictness), func(t *testing.T) {
			opts := ReadOptions{Strictness: strictness, MaxPages: 1000}
			r, err := ParseWithOptions(widePageTree(1000), opts)
			if err != nil || r.PageCount() != 1000 {
				t.Fatalf("exact page limit must succeed: reader=%v, error=%v", r, err)
			}
			for i := range 1000 {
				page, err := r.Page(i)
				if err != nil || page.Width != float64(i+1) {
					t.Fatalf("page %d lost its order or dimensions: %v, %v", i, page, err)
				}
			}
			if _, err := ParseWithOptions(widePageTree(1001), opts); err == nil || !strings.Contains(err.Error(), "page count exceeds limit 1000") {
				t.Fatalf("expected page count error, got %v", err)
			}
			opts.MaxPages = 0
			if _, err := ParseWithOptions(widePageTree(1001), opts); err != nil {
				t.Fatalf("zero must use the larger default: %v", err)
			}
			opts.MaxPages = -1
			if _, err := ParseWithOptions(widePageTree(1), opts); err == nil {
				t.Fatal("negative MaxPages accepted")
			}
		})
	}
}

func TestPageTreeNodeBudget(t *testing.T) {
	for _, strictness := range []Strictness{StrictnessStrict, StrictnessTolerant} {
		t.Run(fmt.Sprint(strictness), func(t *testing.T) {
			// Inline nodes consume traversal budget even though the xref has
			// only three entries. Include non-dictionaries, formerly skipped.
			for _, kid := range []string{"<< /Type /Pages /Kids [] >>", "null"} {
				for _, count := range []int{2, 3} {
					root := "<< /Type /Pages /Kids [" + strings.Repeat(kid+" ", count) + "] /Count 0 >>"
					_, err := ParseWithOptions(pageTreePDF(root), ReadOptions{
						Strictness: strictness, MemoryLimits: MemoryLimits{MaxObjectCount: 3},
					})
					if count == 2 && err != nil {
						t.Fatalf("exact node budget must succeed: %v", err)
					}
					if count == 3 && (err == nil || !strings.Contains(err.Error(), "node budget")) {
						t.Fatalf("expected node budget error, got %v", err)
					}
				}
			}
		})
	}
}

func TestPageTreeDirectDictionaryCycle(t *testing.T) {
	node := core.NewPdfDictionary()
	node.Set("Type", core.NewPdfName("Pages"))
	node.Set("Kids", core.NewPdfArray(node))
	catalog := core.NewPdfDictionary()
	catalog.Set("Pages", node)
	r := &PdfReader{
		catalog:  catalog,
		resolver: newResolver(nil, nil, newMemoryTracker(MemoryLimits{}), StrictnessStrict),
	}
	if err := r.parsePageTree(0); err == nil || !strings.Contains(err.Error(), "revisits dictionary") {
		t.Fatalf("expected direct dictionary revisit error, got %v", err)
	}
}
